/**
 * Milestone rules that need no storage: the state-conflict error, the name key used for uniqueness, the list order and the overdue test.
 *
 * Must call (do not reimplement): normalizeMilestoneName, compareMilestones, isMilestoneOverdue
 */
import type { Milestone } from "@/types/milestone";

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

/** A milestone is in the wrong state for the requested change; mapped to `conflict`. */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: MilestoneStateReason) {
    super(`Milestone state conflict: ${reason}`);
    this.name = "MilestoneStateError";
  }
}

/**
 * The uniqueness key for a milestone name: surrounding spaces and letter case
 * do not make a name distinct within its project.
 */
export function normalizeMilestoneName(name: string): string {
  return name.trim().toLowerCase();
}

/**
 * Open milestones first, then closed; each group by target date (earliest
 * first, undated last), ties by creation time, oldest first.
 */
export function compareMilestones(a: Milestone, b: Milestone): number {
  const aClosed = a.closedAt !== null ? 1 : 0;
  const bClosed = b.closedAt !== null ? 1 : 0;
  if (aClosed !== bClosed) return aClosed - bClosed;

  const aDated = a.targetDate !== null ? 0 : 1;
  const bDated = b.targetDate !== null ? 0 : 1;
  if (aDated !== bDated) return aDated - bDated;

  if (a.targetDate !== null && b.targetDate !== null) {
    const byTarget = Date.parse(a.targetDate) - Date.parse(b.targetDate);
    if (byTarget !== 0) return byTarget;
  }

  return a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : 0;
}

/**
 * Overdue: still open, target date strictly in the past, and at least one open
 * issue left. A milestone without a target date is never overdue.
 */
export function isMilestoneOverdue(
  milestone: Milestone,
  openIssueCount: number,
  now: Date,
): boolean {
  if (milestone.closedAt !== null) return false;
  if (milestone.targetDate === null) return false;
  if (openIssueCount === 0) return false;
  return Date.parse(milestone.targetDate) < now.getTime();
}

