/**
 * Milestone rows and the issue counts behind their progress. Every method takes `orgId` and only counts live (non-archived) issues.
 *
 * Must call (do not reimplement): orgPredicate, toMilestone, CLOSED_ISSUE_STATUSES
 */
import { and, count, eq, inArray, isNull, notInArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp, type IsoTimestamp } from "@/types/common";
import type {
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone } from "@/types/milestone";
import { orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";

export interface MilestoneIssueCounts {
  readonly total: number;
  readonly closed: number;
}

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Looks a name up by its normalized key within one project, closed ones included. */
export async function findMilestoneByNormalizedName(
  orgId: OrgId,
  projectId: ProjectId,
  normalizedName: string,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        eq(milestones.normalizedName, normalizedName),
      ),
    )
    .get();
  return row ? toMilestone(row) : null;
}

export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMilestone(input: {
  orgId: OrgId;
  projectId: ProjectId;
  name: string;
  normalizedName: string;
  targetDate: IsoTimestamp | null;
}): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      normalizedName: input.normalizedName,
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMilestone(row);
}

export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: {
    readonly name?: string;
    readonly normalizedName?: string;
    readonly targetDate?: IsoTimestamp | null;
  },
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.normalizedName === undefined
        ? {}
        : { normalizedName: patch.normalizedName }),
      ...(patch.targetDate === undefined
        ? {}
        : { targetDate: patch.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

export async function setMilestoneClosedAt(
  orgId: OrgId,
  milestoneId: MilestoneId,
  closedAt: IsoTimestamp | null,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Total and closed live-issue counts per milestone, in one grouped query.
 * Milestones with no live issues are absent from the result.
 */
export async function countIssuesByMilestone(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<Readonly<Record<string, MilestoneIssueCounts>>> {
  if (milestoneIds.length === 0) return {};

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        inArray(issues.milestoneId, [...milestoneIds]),
        isNull(issues.archivedAt),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  const counts: Record<string, { total: number; closed: number }> = {};
  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const entry = (counts[row.milestoneId] ??= { total: 0, closed: 0 });
    entry.total += row.value;
    if (CLOSED_ISSUE_STATUSES.includes(row.status)) entry.closed += row.value;
  }
  return counts;
}

/**
 * Closes a milestone and moves its open live issues in one transaction.
 * `moveTo` of `null` takes them out of any milestone. Returns the moved ids.
 */
export async function closeMilestoneMovingOpenIssues(
  orgId: OrgId,
  milestoneId: MilestoneId,
  moveTo: MilestoneId | null,
): Promise<readonly IssueId[]> {
  const now = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const movable = tx
      .select({ id: issues.id })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.milestoneId, milestoneId),
          isNull(issues.archivedAt),
          notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
        ),
      )
      .all()
      .map((row) => row.id as IssueId);

    if (movable.length > 0) {
      tx.update(issues)
        .set({ milestoneId: moveTo, updatedAt: now })
        .where(
          and(orgPredicate(issues.orgId, orgId), inArray(issues.id, movable)),
        )
        .run();
    }

    tx.update(milestones)
      .set({ closedAt: now, updatedAt: now })
      .where(
        and(
          orgPredicate(milestones.orgId, orgId),
          eq(milestones.id, milestoneId),
        ),
      )
      .run();

    return movable;
  });
}

