/**
 * Milestone lifecycle inside a project: naming, the open-milestone cap, closing (which moves open issues) and the progress read.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived, normalizeMilestoneName, compareMilestones, isMilestoneOverdue
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import {
  compareMilestones,
  isMilestoneOverdue,
  MilestoneStateError,
  normalizeMilestoneName,
} from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type {
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneWithProgress,
} from "@/types/milestone";

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = await loadProject(input.orgId, input.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const normalizedName = normalizeMilestoneName(input.name);
  await assertNameFree(input.orgId, project.id, normalizedName, null);
  await assertRoomForOpen(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name: input.name.trim(),
    normalizedName,
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/** Renames and re-dates a milestone. Open and closed milestones alike. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const before = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProject(input.orgId, before.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const patch: {
    name?: string;
    normalizedName?: string;
    targetDate?: Milestone["targetDate"];
  } = {};

  if (input.name !== undefined) {
    const normalizedName = normalizeMilestoneName(input.name);
    await assertNameFree(input.orgId, project.id, normalizedName, before.id);
    patch.name = input.name.trim();
    patch.normalizedName = normalizedName;
  }
  if (input.targetDate !== undefined) {
    patch.targetDate = input.targetDate;
  }

  return milestoneRepo.updateMilestone(input.orgId, before.id, patch);
}

/**
 * Closing moves the milestone's open live issues to `moveOpenIssuesTo` (another
 * open milestone of the same project) or, when none is named, out of any
 * milestone. Each moved issue's assignee is alerted by the notification
 * fan-out, not here.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const milestone = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProject(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  const target = input.moveOpenIssuesTo;
  if (target !== null) {
    if (target === milestone.id) {
      throw new NotFoundError("Milestone", target);
    }
    const destination = await loadMilestone(input.orgId, target);
    if (destination.projectId !== milestone.projectId) {
      throw new NotFoundError("Milestone", target);
    }
    if (destination.closedAt !== null) {
      throw new MilestoneStateError("closed");
    }
  }

  const movedIssueIds = await milestoneRepo.closeMilestoneMovingOpenIssues(
    input.orgId,
    milestone.id,
    target,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
    movedToMilestoneId: target,
    movedIssueIds,
  });

  const closed = await loadMilestone(input.orgId, milestone.id);
  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt === null) {
    throw new MilestoneStateError("already_open");
  }
  await assertRoomForOpen(orgId, project.id);

  const reopened = await milestoneRepo.setMilestoneClosedAt(
    orgId,
    milestone.id,
    null,
  );

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/** Readable by anyone who may read the project, archived or not. */
export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:read", projectResource(project));

  const [withProgress] = await withProgressFor(orgId, [milestone]);
  return withProgress;
}

/** Open milestones first, then closed; see `compareMilestones`. */
export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = await loadProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const milestones = await milestoneRepo.listMilestonesForProject(
    orgId,
    project.id,
  );
  return withProgressFor(orgId, [...milestones].sort(compareMilestones));
}

async function loadProject(orgId: OrgId, projectId: ProjectId) {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
}

async function loadMilestone(orgId: OrgId, milestoneId: MilestoneId) {
  return requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
}

/** `excludeId` is the milestone being renamed, which may keep its own name. */
async function assertNameFree(
  orgId: OrgId,
  projectId: ProjectId,
  normalizedName: string,
  excludeId: MilestoneId | null,
): Promise<void> {
  const holder = await milestoneRepo.findMilestoneByNormalizedName(
    orgId,
    projectId,
    normalizedName,
  );
  if (holder !== null && holder.id !== excludeId) {
    throw new MilestoneStateError("name_taken");
  }
}

async function assertRoomForOpen(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

/** One grouped count covers every milestone in the batch, however many issues they hold. */
async function withProgressFor(
  orgId: OrgId,
  milestones: readonly Milestone[],
): Promise<readonly MilestoneWithProgress[]> {
  const counts = await milestoneRepo.countIssuesByMilestone(
    orgId,
    milestones.map((milestone) => milestone.id),
  );
  const now = new Date();

  return milestones.map((milestone) => {
    const { total = 0, closed = 0 } = counts[milestone.id] ?? {};
    const open = total - closed;
    return {
      milestone,
      progress: { total, open, closed },
      overdue: isMilestoneOverdue(milestone, open, now),
    };
  });
}

