vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { MilestoneStateError } from "@/lib/milestones";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import * as notificationService from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("milestonesvc");
});

afterAll(() => {
  cleanup();
});

function milestoneBase() {
  return { orgId: tenant.org.id, projectId: tenant.project.id };
}

describe("services/milestone-service", () => {
  it("refuses a name already used in the project, ignoring case and surrounding spaces", async () => {
    await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneBase(),
      name: "Beta",
      targetDate: null,
    });

    await expect(
      milestoneService.createMilestone(tenant.actors.member, {
        ...milestoneBase(),
        name: "  beta ",
        targetDate: null,
      }),
    ).rejects.toMatchObject({ reason: "name_taken" });
  });

  it("refuses a viewer who may not update the project", async () => {
    await expect(
      milestoneService.createMilestone(tenant.actors.viewer, {
        ...milestoneBase(),
        name: "Not for viewers",
        targetDate: null,
      }),
    ).rejects.toMatchObject({ code: "forbidden" });
  });

  it("refuses to reopen an open milestone and to close one into itself", async () => {
    const milestone = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneBase(),
      name: "Gamma",
      targetDate: null,
    });

    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, milestone.id),
    ).rejects.toMatchObject({ reason: "already_open" });

    await expect(
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: milestone.id,
        moveOpenIssuesTo: milestone.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("moves open issues on close, alerts each assignee once, and leaves closed issues in place", async () => {
    const source = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneBase(),
      name: "Source",
      targetDate: null,
    });
    const destination = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneBase(),
      name: "Destination",
      targetDate: null,
    });

    const openIssue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Still open",
        assigneeId: tenant.userIds.member,
        milestoneId: source.id,
      }),
    );
    const doneIssue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already done",
        status: "done",
        milestoneId: source.id,
      }),
    );

    const { milestone, movedIssueIds } = await milestoneService.closeMilestone(
      tenant.actors.owner,
      {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: destination.id,
      },
    );

    expect(milestone.closedAt).not.toBeNull();
    expect(movedIssueIds).toEqual([openIssue.id]);

    const moved = await issueRepo.findIssueById(tenant.org.id, openIssue.id);
    const stayed = await issueRepo.findIssueById(tenant.org.id, doneIssue.id);
    expect(moved?.milestoneId).toBe(destination.id);
    expect(stayed?.milestoneId).toBe(source.id);

    const feed = await notificationService.listNotifications(tenant.actors.member, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      limit: 100,
      cursor: null,
    });
    const alerts = feed.items.filter(
      (notification) =>
        notification.kind === "issue_milestone_changed" &&
        notification.href === `/issues/${openIssue.id}`,
    );
    expect(alerts).toHaveLength(1);
  });

  it("refuses to move an issue into a closed milestone and leaves it unchanged", async () => {
    const closed = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneBase(),
      name: "Closed target",
      targetDate: null,
    });
    await milestoneService.closeMilestone(tenant.actors.owner, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Stays put" }),
    );

    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: closed.id,
      }),
    ).rejects.toBeInstanceOf(MilestoneStateError);

    const after = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(after?.milestoneId).toBeNull();
  });

  it("caps open milestones per project, and counts a reopened one against the cap", async () => {
    const capped = await createTenant("milestonecap");
    const base = { orgId: capped.org.id, projectId: capped.project.id };

    const created = [];
    for (let index = 0; index < MAX_OPEN_MILESTONES_PER_PROJECT; index += 1) {
      created.push(
        await milestoneService.createMilestone(capped.actors.member, {
          ...base,
          name: `Cap ${index}`,
          targetDate: null,
        }),
      );
    }

    await expect(
      milestoneService.createMilestone(capped.actors.member, {
        ...base,
        name: "One too many",
        targetDate: null,
      }),
    ).rejects.toMatchObject({ reason: "too_many_open" });

    await milestoneService.closeMilestone(capped.actors.owner, {
      orgId: capped.org.id,
      milestoneId: created[0].id,
      moveOpenIssuesTo: null,
    });

    const reopened = await milestoneService.createMilestone(capped.actors.member, {
      ...base,
      name: "Fits after close",
      targetDate: null,
    });
    expect(reopened.closedAt).toBeNull();

    await expect(
      milestoneService.reopenMilestone(capped.actors.member, capped.org.id, created[0].id),
    ).rejects.toMatchObject({ reason: "too_many_open" });
  });

  it("lists open milestones before closed ones, with progress and overdue flags", async () => {
    const listing = await createTenant("milestonelist");
    const base = { orgId: listing.org.id, projectId: listing.project.id };

    const late = await milestoneService.createMilestone(listing.actors.member, {
      ...base,
      name: "Late",
      targetDate: "2020-01-01T00:00:00.000Z",
    });
    const undated = await milestoneService.createMilestone(listing.actors.member, {
      ...base,
      name: "Undated",
      targetDate: null,
    });
    const shut = await milestoneService.createMilestone(listing.actors.member, {
      ...base,
      name: "Shut",
      targetDate: null,
    });
    await milestoneService.closeMilestone(listing.actors.owner, {
      orgId: listing.org.id,
      milestoneId: shut.id,
      moveOpenIssuesTo: null,
    });

    await issueService.createIssue(
      listing.actors.member,
      issueInput(listing.org.id, listing.project.id, {
        title: "Counted open",
        milestoneId: late.id,
      }),
    );
    await issueService.createIssue(
      listing.actors.member,
      issueInput(listing.org.id, listing.project.id, {
        title: "Counted done",
        status: "canceled",
        milestoneId: late.id,
      }),
    );

    const rows = await milestoneService.listMilestones(
      listing.actors.viewer,
      listing.org.id,
      listing.project.id,
    );

    expect(rows.map((row) => row.milestone.id)).toEqual([
      late.id,
      undated.id,
      shut.id,
    ]);
    expect(rows[0].progress).toEqual({ total: 2, open: 1, closed: 1 });
    expect(rows[0].overdue).toBe(true);
    expect(rows[1].overdue).toBe(false);
    expect(rows[2].milestone.closedAt).not.toBeNull();
  });
});

